CREATE WORKLOAD GROUP wgLoads
WITH
  ( MIN_PERCENTAGE_RESOURCE = 60                
    , CAP_PERCENTAGE_RESOURCE = 80
    , REQUEST_MIN_RESOURCE_GRANT_PERCENT = 10 -- Parallelism shall be defined as 6 = 60 / 10
  );

CREATE WORKLOAD GROUP wgReporting
WITH ( MIN_PERCENTAGE_RESOURCE = 40
      ,CAP_PERCENTAGE_RESOURCE = 80
      ,REQUEST_MIN_RESOURCE_GRANT_PERCENT = 2 -- 20 parallel queries should be expected, because 40 / 2 = 20
      ,QUERY_EXECUTION_TIMEOUT_SEC = 30 
      ,QUERY_WAIT_TIMEOUT_SEC = 30 );

   CREATE WORKLOAD CLASSIFIER wgETLAdmin
   WITH (
	     WORKLOAD_GROUP = 'wgDataLoads'
       , MEMBERNAME = 'ericpasztor@microsoft.com'
      , IMPORTANCE = ABOVE_NORMAL
   );

CREATE WORKLOAD CLASSIFIER [wgcLoads]
WITH (WORKLOAD_GROUP = 'wgDataLoads'
      ,MEMBERNAME = 'ELTUser');


CREATE WORKLOAD CLASSIFIER [wgcReporting]
WITH (WORKLOAD_GROUP = 'wgReporting'
      ,MEMBERNAME = 'Analyst');

CREATE WORKLOAD CLASSIFIER [wgcCFO]
WITH (WORKLOAD_GROUP = 'wgDashboard'
      ,MEMBERNAME = 'CFO');

SELECT group_id, name, importance, min_percentage_resource, cap_percentage_resource, request_min_resource_grant_percent, request_max_resource_grant_percent, query_execution_timeout_sec, query_wait_timeout_sec 
    FROM sys.workload_management_workload_groups;

   SELECT name
FROM   sys.database_principals
WHERE  name LIKE '%rc%' AND type_desc = 'DATABASE_ROLE';

SELECT  r.name AS [Resource Class]
,       m.name AS membername
FROM    sys.database_role_members rm
JOIN    sys.database_principals AS r ON rm.role_principal_id = r.principal_id
JOIN    sys.database_principals AS m ON rm.member_principal_id = m.principal_id
WHERE   r.name IN ('mediumrc','largerc','xlargerc','staticrc10','staticrc20','staticrc30','staticrc40','staticrc50','staticrc60','staticrc70','staticrc80');

ALTER DATABASE dsqlnonprod
